#include <bits/stdc++.h>
using namespace std;

int main() {
    int n = 5;
    vector<vector<pair<int, int>>> adj(n);                 // (sąsiad, waga)
    auto kr = [&](int a, int b, int w) { adj[a].push_back({b, w}); adj[b].push_back({a, w}); };
    kr(0, 1, 4); kr(0, 2, 1); kr(2, 1, 2); kr(1, 3, 5); kr(3, 4, 3);

    const long long INF = LLONG_MAX;
    vector<long long> dist(n, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
    dist[0] = 0;
    pq.push({0, 0});
    while (!pq.empty()) {
        auto [d, v] = pq.top();
        pq.pop();
        if (d > dist[v]) continue;                         // nieaktualny wpis — pomiń
        for (auto [u, w] : adj[v])
            if (dist[v] + w < dist[u]) {
                dist[u] = dist[v] + w;
                pq.push({dist[u], u});
            }
    }
    for (int v = 0; v < n; v++) cout << dist[v] << ' ';    // 0 3 1 8 11
    cout << '\n';
}

