#include <bits/stdc++.h>
using namespace std;

// maksimum w każdym oknie długości k w O(n) — kolejka monotoniczna
int main() {
    vector<int> a = {1, 3, -1, -3, 5, 3, 6, 7};
    int k = 3;
    deque<int> dq;                 // indeksy; wartości a[] malejące od przodu
    for (int i = 0; i < (int)a.size(); i++) {
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
        dq.push_back(i);
        if (dq.front() <= i - k) dq.pop_front();   // wypadł z okna
        if (i >= k - 1) cout << a[dq.front()] << ' ';
    }
    cout << '\n';                  // 3 3 5 5 6 7
}

#include <bits/stdc++.h>
