// 0-1 BFS: krawędzie o wagach 0 lub 1, najkrótsze ścieżki w O(n + m)
int main() {
    int n = 4;
    vector<vector<pair<int, int>>> adj(n);   // (sąsiad, waga 0/1)
    adj[0] = {{1, 1}, {2, 0}};
    adj[2] = {{1, 0}, {3, 1}};
    adj[1] = {{3, 1}};
    vector<int> dist(n, INT_MAX);
    deque<int> dq;
    dist[0] = 0;
    dq.push_back(0);
    while (!dq.empty()) {
        int v = dq.front();
        dq.pop_front();
        for (auto [u, w] : adj[v])
            if (dist[v] + w < dist[u]) {
                dist[u] = dist[v] + w;
                if (w == 0) dq.push_front(u);
                else dq.push_back(u);
            }
    }
    for (int d : dist) cout << d << ' ';     // 0 0 0 1
    cout << '\n';
}

