vector<int> nxt(n + 2), prv(n + 2);
for (int i = 0; i <= n + 1; i++) { nxt[i] = i + 1; prv[i] = i - 1; }   // 0 i n+1 to strażnicy
auto usun = [&](int i) { nxt[prv[i]] = nxt[i]; prv[nxt[i]] = prv[i]; };
usun(3);
usun(1);
for (int i = nxt[0]; i <= n; i = nxt[i]) cout << i << ' ';   // 2 4 5
cout << '\n';

